<?php declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\Shared\{Db,RuntimeSchema,Schema,SecretBox,Access};use Kulturhus\Native\Pos\{Register,Web};use Kulturhus\Native\Integration\{ManagerBridge,Accounts};use Kulturhus\Verein\{Database,Finance};
$db=\Kulturhus\Native\TestSupport::db();Database::migrate($db);Schema::install($db);RuntimeSchema::install($db);\Kulturhus\Native\Pos\Schema::install($db);$db->exec("INSERT INTO clubs VALUES('preflight-club','Synthetic');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('cashier','preflight-club','member',1)");$club=ManagerBridge::clubKey('preflight-club');Db::run($db,'INSERT INTO native_users VALUES(?,?,?,1)',['native-cashier',$club,'Synthetic']);Db::run($db,"INSERT INTO native_grants VALUES('native-cashier','website','manage')");$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/preflight-key-'.bin2hex(random_bytes(5));file_put_contents($root,str_repeat('s',32));chmod($root,0600);putenv('KH_NATIVE_PRIVATE_KEY_FILE='.$root);(new Accounts($db,SecretBox::fromFile($root)))->save(new Access($db,'native-cashier'),'sumup',['merchant_code'=>'SYNTHETICMERCH','token'=>'explicit-test-token'],0);
$event=bin2hex(random_bytes(16));Db::run($db,'INSERT INTO event_voucher_events(club_id,id,source_id,title,starts_at,location) VALUES(?,?,?,?,?,?)',['preflight-club',$event,'synthetic-preflight','Synthetic preflight','2026-10-08T18:00:00Z','Saal']);$register=new Register($db,'cashier');$account=(new Finance($db,'cashier'))->createAccount('Synthetic cash','cash','0','2026-01-01');$shift=$register->open($event,$account,0);$product=$register->saveProduct(['label'=>'Synthetic goods','price'=>'3.00','sphere'=>'wirtschaftlich']);$sale=$register->cart($shift,[['id'=>$product,'quantity'=>1]],0,bin2hex(random_bytes(16)));$sale=$register->tender($sale['id'],$sale['version'],0);$attempt=$register->attempt($sale['id'],'sumup-tap');$csrf=str_repeat('a',64);$web=new Web($db,$register,'cashier',$csrf);$n=0;function check(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);$n++;echo "PASS $label\n";}function denied(callable $f,string $label):void{try{$f();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$preflight=$web->action(['operation'=>'native-info','payment'=>$attempt['id'],'csrf'=>$csrf]);check($preflight['native']['amount_cents']===300&&$preflight['native']['merchant_code']==='SYNTHETICMERCH'&&$preflight['native']['reference']===$attempt['reference'],'native read-only instructions bind exact amount, merchant and reference');check($register->payment($attempt['id'])['state']==='prepared','availability preflight leaves durable attempt unstarted');denied(fn()=>$web->action(['operation'=>'native-info','payment'=>$attempt['id'],'csrf'=>'bad']),'preflight requires current CSRF');$web->action(['operation'=>'cancel-attempt','payment'=>$attempt['id'],'csrf'=>$csrf]);check($register->payment($attempt['id'])['state']==='cancelled','unavailable device can abandon only unstarted attempt');$next=$register->attempt($sale['id'],'sumup-reader');check($next['id']!==$attempt['id']&&$next['state']==='prepared','other payment way can be chosen after safe cancellation');$info=$web->action(['operation'=>'native-info','payment'=>$next['id'],'csrf'=>$csrf]);$started=$web->action(['operation'=>'native-start','payment'=>$next['id'],'csrf'=>$csrf]);check($started['native']===$info['native']&&$register->payment($next['id'])['state']==='pending','native start persists attempt after availability and returns same bound instructions');denied(fn()=>$register->cancelPrepared($next['id']),'started device attempt cannot be cancelled as unstarted');denied(fn()=>$web->action(['operation'=>'native-info','payment'=>$next['id'],'csrf'=>$csrf]),'existing device attempt cannot obtain a fresh preflight');denied(fn()=>$web->action(['operation'=>'native-start','payment'=>$next['id'],'csrf'=>$csrf]),'device start is never replayed');check($register->sale($sale['id'])['state']==='payment','native device start does not claim paid sale');unlink($root);echo "$n native device preflight checks passed; no SDK/device or provider call.\n";
